#!/usr/bin/env python3
"""Fetch contacts from the email-api server and save a formatted list to contacts.txt."""
import json
import sys
import urllib.request

API_BASE = "https://agenskill-api.onrender.com"
API_KEY = "sk-email-api-742189hd023"
USER_EMAIL = "noah.dac@aisa.io"
OUTPUT_FILE = "contacts.txt"

req = urllib.request.Request(
    API_BASE + "/contacts",
    headers={
        "X-API-Key": API_KEY,
        "X-User-Email": USER_EMAIL,
        "Accept": "application/json",
    },
)

try:
    with urllib.request.urlopen(req, timeout=60) as resp:
        raw = resp.read().decode("utf-8")
except urllib.error.HTTPError as e:
    print("HTTP error:", e.code, e.read().decode("utf-8", "replace"), file=sys.stderr)
    sys.exit(1)
except urllib.error.URLError as e:
    print("Connection error:", e, file=sys.stderr)
    sys.exit(1)

data = json.loads(raw)
print("RAW RESPONSE:")
print(json.dumps(data, indent=2))

# Try to locate the contacts list in the response (dict with a list value, or a bare list)
contacts = None
if isinstance(data, list):
    contacts = data
elif isinstance(data, dict):
    for key in ("contacts", "data", "items", "results"):
        if key in data and isinstance(data[key], list):
            contacts = data[key]
            break
    if contacts is None:
        # fall back to any list value in the dict
        for value in data.values():
            if isinstance(value, list):
                contacts = value
                break

if contacts is None:
    print("Could not locate a contacts list in the response.", file=sys.stderr)
    sys.exit(2)

lines = []
for i, c in enumerate(contacts, start=1):
    if isinstance(c, dict):
        name = c.get("name") or c.get("fullName") or c.get("full_name") or ""
        email = c.get("email") or c.get("address") or ""
        if name and email:
            lines.append(f"{i}. {name} <{email}>")
        elif email:
            lines.append(f"{i}. {email}")
        else:
            lines.append(f"{i}. {json.dumps(c)}")
    else:
        lines.append(f"{i}. {c}")

with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
    f.write("Contacts for " + USER_EMAIL + "\n")
    f.write("=" * 50 + "\n")
    if lines:
        f.write("\n".join(lines) + "\n")
    else:
        f.write("(no contacts found)\n")

print(f"\nWrote {len(lines)} contact(s) to {OUTPUT_FILE}")

#!/usr/bin/env python3
"""Fetch contacts from the email API and print one contact per line."""
import json
import sys
import urllib.request

BASE_URL = "https://agenskill-api.onrender.com"


def main():
    with open("email_credentials.json") as f:
        creds = json.load(f)
    account = creds["account"]
    email = account["email"]
    api_key = account["api_key"]

    req = urllib.request.Request(
        BASE_URL + "/contacts",
        headers={"X-API-Key": api_key, "X-User-Email": email},
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            data = json.load(resp)
    except Exception as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        sys.exit(1)

    if not data.get("success", False):
        print(f"ERROR: {data.get('error', 'unknown error')}", file=sys.stderr)
        sys.exit(1)

    contacts = data.get("contacts", [])
    if not contacts:
        print("(no contacts found)")
        return

    for c in contacts:
        name = (c.get("name") or "").strip()
        em = (c.get("email") or "").strip()
        if name and em:
            print(f"{name} <{em}>")
        elif em:
            print(em)
        elif name:
            print(name)


if __name__ == "__main__":
    main()
